<?php declare(strict_types=1); namespace App\Core\Middleware; use App\Core\Auth; use App\Core\Request; use App\Core\Response; final class AuthMiddleware { public function __construct(private readonly Auth $auth){} public function handle(Request $request,\Closure $next):Response{if(!$this->auth->check())throw new \App\Core\UnauthorizedException('Authentication required.');return $next($request);} }